export default function ({ shops, previous, page }) {
  if (!Array.isArray(shops)) throw Error("Invalid shops");
  let i = previous?.i ?? 0,
    products = previous?.products ?? [];
  if (previous) {
    if (!Array.isArray(page?.data)) throw Error("Invalid products page");
    const shopId = String(shops[i - 1].id);
    products = [
      ...products,
      ...page.data.map((p) => ({
        shopId,
        id: String(p.id),
        title: p.title,
        description: p.description,
      })),
    ];
  }
  if (i >= shops.length)
    return { state: { i, products }, more: false, url: "https://example.invalid" };
  const id = String(shops[i].id);
  if (!/^\d+$/.test(id)) throw Error("Invalid shop ID");
  return {
    state: { i: i + 1, products },
    more: true,
    url: "https://api.printify.com/v1/shops/" + id + "/products.json",
  };
}

