export default function ({ products, previous }) {
  let i = previous?.i ?? 0,
    option = previous?.option ?? 0;
  if (previous) {
    option++;
    if (option >= 3) {
      i++;
      option = 0;
    }
  }
  if (i >= products.length) return { state: { i, option }, more: false, product: {}, option: 0 };
  const product = products[i];
  if (!product.id || typeof product.title !== "string" || typeof product.description !== "string")
    throw Error("Invalid product");
  return { state: { i, option }, more: true, product, option };
}

