export default async function ({ runId, product, option, copy }, ctx) {
  if (!runId.trim() || !copy?.keyword || !copy?.title || !copy?.description)
    throw Error("Invalid option");
  const xid = [runId, product.shopId, product.id, option + 1].join(":"),
    key = "printify-option:" + xid;
  if (await ctx.state.get(key)) throw Error("Prior option write needs reconciliation");
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    values: [
      [
        xid,
        new Date().toISOString(),
        "Option added",
        product.shopId,
        product.id,
        product.title,
        product.description,
        copy.keyword,
        copy.title,
        copy.description,
        "",
      ],
    ],
  };
}

