export default async function ({ rows }, ctx) {
  if (!Array.isArray(rows) || !rows.length) throw Error("Missing sheet");
  const h = rows[0],
    required = ["xid", "shop_id", "product_id", "product_title", "product_desc", "upload"],
    idx = Object.fromEntries(required.map((k) => [k, h.indexOf(k)]));
  if (required.some((k) => idx[k] < 0)) throw Error("Missing sheet headers");
  const snapshot = {},
    all = [];
  for (const r of rows.slice(1)) {
    const id = String(r[idx.xid] ?? "");
    if (!id) continue;
    if (Object.hasOwn(snapshot, id)) throw Error("Duplicate xid");
    snapshot[id] = String(r[idx.upload] ?? "");
    all.push({
      xid: id,
      shopId: String(r[idx.shop_id] ?? ""),
      productId: String(r[idx.product_id] ?? ""),
      title: String(r[idx.product_title] ?? ""),
      description: String(r[idx.product_desc] ?? ""),
      upload: snapshot[id],
    });
  }
  const prior = await ctx.state.get("printify-sheet-snapshot"),
    version = (await ctx.state.get("printify-sheet-version")) ?? 0,
    queue = prior
      ? all.filter(
          (r) => Object.hasOwn(prior, r.xid) && prior[r.xid] !== r.upload && r.upload === "yes",
        )
      : [];
  return { snapshot, queue, generation: prior ? version + 1 : version };
}

