export default async function ({ row, generation }, ctx) {
  if (
    !/^\d+$/.test(row.shopId) ||
    !/^[A-Za-z0-9_-]+$/.test(row.productId) ||
    !row.title ||
    !row.description
  )
    throw Error("Missing shop, product or approved copy");
  const key = "printify-upload:" + generation + ":" + row.xid,
    fingerprint = JSON.stringify(row),
    old = await ctx.state.get(key);
  if (old && old.fingerprint !== fingerprint) throw Error("Changed pending row; inspect");
  if (old?.status === "done") return { key, skip: true, url: "https://example.invalid", body: {} };
  if (old) throw Error("Prior product update unknown; inspect Printify");
  await ctx.state.set(key, { status: "pending", fingerprint });
  return {
    key,
    skip: false,
    url: "https://api.printify.com/v1/shops/" + row.shopId + "/products/" + row.productId + ".json",
    body: { title: row.title, description: row.description },
  };
}

