export default async function ({ key, row, body }, ctx) {
  if (!body || String(body.id) !== row.productId) throw Error("Unknown Printify update outcome");
  const old = await ctx.state.get(key);
  await ctx.state.set(key, { ...old, status: "done" });
  return { done: true };
}

